def replace(self, key: URL, msg: str) -> None:
        for i in range(len(self.lines))[::-1]:
            line = self.lines[i]
            if line[0] == key:
                self.lines[i] = (key, False, msg)
                self.first_line = min(self.first_line, i)
                self.last_line = max(self.last_line, i + 1)
                self.maybe_flush()
                break
        else:
            self._append_file(key, msg)
